);

  wire       [23:0]   _zz_cmdAddress;
  wire       [15:0]   _zz_statusReadData;
  wire       [15:0]   _zz_captureMetaNow;
  wire       [23:0]   wedgedStatusAddr;
  wire       [23:0]   debugLiveAddr;
  wire       [23:0]   debugCapturedAddressAddr;
  wire       [23:0]   debugCapturedDataAddr;
  wire       [23:0]   debugCapturedMetaAddr;
