  wire                illegalReq;
  wire                selectedReadReq;
  wire                hasReq;
  wire                statusReadReq;
  wire                debugLiveReadReq;
  wire                debugCapturedAddressReadReq;
  wire                debugCapturedDataReadReq;
  wire                debugCapturedMetaReadReq;
  wire                debugReadReq;
  reg                 cmdInFlight;
  reg                 readRspPending;
  reg        [31:0]   readData;
  reg                 readDataValid;
  reg                 readDataPending;
  reg                 wedged;
  reg        [20:0]   requestStallCycles;
  reg        [20:0]   responseStallCycles;
  reg        [20:0]   wedgedWriteStallCycles;
  reg        [7:0]    droppedWrites;
  reg                 requestTimeoutSeen;
  reg                 responseTimeoutSeen;
  reg                 capturedValid;
  reg        [23:0]   capturedAddress;
  reg        [31:0]   capturedData;
  reg        [31:0]   capturedMeta;
  wire                cmdBlocked;
  wire                wedgedReadReq;
  wire                localReadReq;
  wire                localWriteReq;
  wire                locallyHandledReq;
  wire                readResponseSlotAvailable;
  wire                localReadAccept;
  wire                localWriteAccept;
  wire                localAccept;
  wire                canIssueReq;
  wire                acceptWindow;
  wire                requestStalled;
  wire                requestStallLimitReached;
  wire                requestTimeoutAccept;
  wire                requestTimeoutRead;
  wire                requestTimeoutWrite;
  wire                localOrRequestTimeoutRead;
  wire                rspFire;
  wire                cpuCmdFire;
  wire                rspCompletesCurrent;
  wire                rspIsRead;
  wire                responseStallLimitReached;
  wire                responseTimeoutRead;
  wire                responseTimeoutWrite;
  wire                responseTimeout;
  wire                wedgeNow;
  reg        [31:0]   statusReadData;
  reg        [31:0]   debugLiveData;
  reg        [31:0]   capturedAddressData;
  reg        [31:0]   localReadData;
  wire                when_CoreDe10_l197;
  wire                when_CoreDe10_l204;
  wire                when_CoreDe10_l207;
  wire                captureNow;
  reg        [31:0]   captureMetaNow;
  wire                when_CoreDe10_l263;
  wire                when_CoreDe10_l264;
  wire                when_CoreDe10_l269;
  wire                when_CoreDe10_l283;

  assign _zz_cmdAddress = {2'd0, io_h2fLw_address};
  assign _zz_statusReadData = wedgedWriteStallCycles[15:0];
  assign _zz_captureMetaNow = requestStallCycles[15:0];
  assign wedgedStatusAddr = 24'h000254;
  assign debugLiveAddr = 24'h000258;
  assign debugCapturedAddressAddr = 24'h00025c;
  assign debugCapturedDataAddr = 24'h000260;
  assign debugCapturedMetaAddr = 24'h000264;
  assign cmdAddress = (_zz_cmdAddress <<< 2);
  assign illegalReq = (io_h2fLw_write && io_h2fLw_read);
  assign selectedReadReq = ((! io_h2fLw_write) && io_h2fLw_read);
  assign hasReq = (io_h2fLw_write || io_h2fLw_read);
  assign statusReadReq = (selectedReadReq && (cmdAddress == wedgedStatusAddr));
  assign debugLiveReadReq = (selectedReadReq && (cmdAddress == debugLiveAddr));
  assign debugCapturedAddressReadReq = (selectedReadReq && (cmdAddress == debugCapturedAddressAddr));
  assign debugCapturedDataReadReq = (selectedReadReq && (cmdAddress == debugCapturedDataAddr));
  assign debugCapturedMetaReadReq = (selectedReadReq && (cmdAddress == debugCapturedMetaAddr));
  assign debugReadReq = ((((statusReadReq || debugLiveReadReq) || debugCapturedAddressReadReq) || debugCapturedDataReadReq) || debugCapturedMetaReadReq);
  assign io_cpuBus_cmd_payload_last = 1'b1;
  assign io_cpuBus_cmd_payload_fragment_source = 4'b0000;
  always @(*) begin
    io_cpuBus_cmd_payload_fragment_opcode = 1'b0;
    if(io_h2fLw_write) begin
      io_cpuBus_cmd_payload_fragment_opcode = 1'b1;
    end else begin
      io_cpuBus_cmd_payload_fragment_opcode = 1'b0;
    end
  end

  assign io_cpuBus_cmd_payload_fragment_address = cmdAddress;
  assign io_cpuBus_cmd_payload_fragment_length = 2'b11;
  assign io_cpuBus_cmd_payload_fragment_data = io_h2fLw_writedata;
  assign io_cpuBus_cmd_payload_fragment_mask = io_h2fLw_byteenable;
  assign cmdBlocked = (((cmdInFlight || readRspPending) || readDataPending) || readDataValid);
  assign wedgedReadReq = ((selectedReadReq && wedged) && (! debugReadReq));
  assign localReadReq = (debugReadReq || wedgedReadReq);
  assign localWriteReq = (io_h2fLw_write && wedged);
  assign locallyHandledReq = (localReadReq || localWriteReq);
  assign readResponseSlotAvailable = ((! readDataPending) && (! readDataValid));
  assign localReadAccept = (localReadReq && readResponseSlotAvailable);
  assign localWriteAccept = (localWriteReq && (! illegalReq));
  assign localAccept = ((hasReq && (! illegalReq)) && (localReadAccept || localWriteAccept));
  assign canIssueReq = (((hasReq && (! illegalReq)) && (! cmdBlocked)) && (! locallyHandledReq));
  assign acceptWindow = (canIssueReq && io_cpuBus_cmd_ready);
  assign requestStalled = ((((hasReq && (! illegalReq)) && (! locallyHandledReq)) && (! acceptWindow)) && (cmdBlocked || (! io_cpuBus_cmd_ready)));
  assign requestStallLimitReached = (requestStalled && (requestStallCycles == 21'h0fffff));
  assign requestTimeoutAccept = (requestStallLimitReached && (io_h2fLw_write || readResponseSlotAvailable));
  assign requestTimeoutRead = (requestTimeoutAccept && selectedReadReq);
  assign requestTimeoutWrite = (requestTimeoutAccept && io_h2fLw_write);
  assign localOrRequestTimeoutRead = (localReadAccept || requestTimeoutRead);
  assign io_cpuBus_rsp_ready = (readResponseSlotAvailable && (! localOrRequestTimeoutRead));
  assign rspFire = (io_cpuBus_rsp_valid && io_cpuBus_rsp_ready);
  assign cpuCmdFire = (io_cpuBus_cmd_valid && io_cpuBus_cmd_ready);
  assign rspCompletesCurrent = (rspFire && (cmdInFlight || acceptWindow));
  assign rspIsRead = ((cmdInFlight && readRspPending) || (acceptWindow && selectedReadReq));
  assign responseStallLimitReached = ((cmdInFlight && (! rspFire)) && (responseStallCycles == 21'h0fffff));
  assign responseTimeoutRead = (((responseStallLimitReached && readRspPending) && readResponseSlotAvailable) && (! localOrRequestTimeoutRead));
  assign responseTimeoutWrite = (responseStallLimitReached && (! readRspPending));
  assign responseTimeout = (responseTimeoutRead || responseTimeoutWrite);
  assign wedgeNow = (requestTimeoutAccept || responseTimeout);
  always @(*) begin
    statusReadData = 32'h0;
    statusReadData[0] = (wedged || wedgeNow);
    statusReadData[1] = (requestTimeoutSeen || requestTimeoutAccept);
    statusReadData[2] = (responseTimeoutSeen || responseTimeout);
    statusReadData[4] = cmdInFlight;
    statusReadData[5] = readRspPending;
    statusReadData[15 : 8] = droppedWrites;
    statusReadData[31 : 16] = _zz_statusReadData;
  end

  always @(*) begin
    debugLiveData = 32'h0;
    debugLiveData[0] = hasReq;
    debugLiveData[1] = io_h2fLw_write;
    debugLiveData[2] = io_h2fLw_read;
    debugLiveData[3] = illegalReq;
    debugLiveData[4] = debugReadReq;
    debugLiveData[5] = localWriteReq;
    debugLiveData[6] = localAccept;
    debugLiveData[7] = acceptWindow;
    debugLiveData[8] = io_cpuBus_cmd_valid;
    debugLiveData[9] = io_cpuBus_cmd_ready;
    debugLiveData[10] = cpuCmdFire;
    debugLiveData[11] = io_cpuBus_rsp_valid;
    debugLiveData[12] = io_cpuBus_rsp_ready;
    debugLiveData[13] = rspFire;
    debugLiveData[14] = cmdBlocked;
    debugLiveData[15] = cmdInFlight;
    debugLiveData[16] = readRspPending;
    debugLiveData[17] = readDataPending;
    debugLiveData[18] = readDataValid;
    debugLiveData[19] = requestStalled;
    debugLiveData[20] = requestTimeoutAccept;
    debugLiveData[21] = responseTimeout;
    debugLiveData[22] = wedged;
    debugLiveData[23] = wedgeNow;
    debugLiveData[24] = readResponseSlotAvailable;
    debugLiveData[25] = locallyHandledReq;
    debugLiveData[26] = canIssueReq;
    debugLiveData[27] = localReadAccept;
    debugLiveData[28] = localWriteAccept;
    debugLiveData[29] = rspCompletesCurrent;
    debugLiveData[30] = selectedReadReq;
    debugLiveData[31] = capturedValid;
  end

  always @(*) begin
    capturedAddressData = 32'h0;
    capturedAddressData[23 : 0] = capturedAddress;
  end

  always @(*) begin
    localReadData = 32'h0;
    if(statusReadReq) begin
      localReadData = statusReadData;
    end
    if(debugLiveReadReq) begin
      localReadData = debugLiveData;
    end
    if(debugCapturedAddressReadReq) begin
      localReadData = capturedAddressData;
    end
    if(debugCapturedDataReadReq) begin
      localReadData = capturedData;
    end
    if(debugCapturedMetaReadReq) begin
      localReadData = capturedMeta;
    end
  end

  assign io_h2fLw_waitrequest = (hasReq && (! ((localAccept || requestTimeoutAccept) || acceptWindow)));
  assign io_h2fLw_readdata = readData;
  assign io_h2fLw_readdatavalid = readDataValid;
  assign when_CoreDe10_l197 = (requestStallCycles != 21'h0fffff);
  assign when_CoreDe10_l204 = (cmdInFlight && (! rspFire));
  assign when_CoreDe10_l207 = (responseStallCycles != 21'h0fffff);
  assign captureNow = (((hasReq && (! illegalReq)) && (! debugReadReq)) && (((requestStalled || acceptWindow) || localWriteAccept) || requestTimeoutAccept));
  always @(*) begin
    captureMetaNow = 32'h0;
    captureMetaNow[0] = 1'b1;
    captureMetaNow[1] = io_h2fLw_write;
    captureMetaNow[2] = selectedReadReq;
    captureMetaNow[3] = requestStalled;
    captureMetaNow[4] = acceptWindow;
    captureMetaNow[5] = requestTimeoutAccept;
    captureMetaNow[6] = responseTimeout;
    captureMetaNow[7] = localWriteAccept;
    captureMetaNow[8] = io_cpuBus_cmd_ready;
    captureMetaNow[9] = cmdBlocked;
    captureMetaNow[10] = wedged;
    captureMetaNow[15 : 12] = io_h2fLw_byteenable;
    captureMetaNow[31 : 16] = _zz_captureMetaNow;
  end

  assign io_cpuBus_cmd_valid = canIssueReq;
  assign when_CoreDe10_l263 = (localWriteAccept || requestTimeoutWrite);
  assign when_CoreDe10_l264 = (droppedWrites != 8'hff);
  assign when_CoreDe10_l269 = (acceptWindow && (! rspCompletesCurrent));
  assign when_CoreDe10_l283 = (requestTimeoutRead || responseTimeoutRead);
  always @(posedge clk or posedge reset) begin
    if(reset) begin
      cmdInFlight <= 1'b0;
      readRspPending <= 1'b0;
      readData <= 32'h0;
      readDataValid <= 1'b0;
      readDataPending <= 1'b0;
      wedged <= 1'b0;
      requestStallCycles <= 21'h0;
      responseStallCycles <= 21'h0;
      wedgedWriteStallCycles <= 21'h0;
      droppedWrites <= 8'h0;
      requestTimeoutSeen <= 1'b0;
      responseTimeoutSeen <= 1'b0;
      capturedValid <= 1'b0;
      capturedAddress <= 24'h0;
      capturedData <= 32'h0;
      capturedMeta <= 32'h0;
    end else begin
      readDataValid <= 1'b0;
      if(requestStalled) begin
        if(requestTimeoutAccept) begin
          requestStallCycles <= 21'h0;
        end else begin
          if(when_CoreDe10_l197) begin
            requestStallCycles <= (requestStallCycles + 21'h000001);
          end
        end
      end else begin
        requestStallCycles <= 21'h0;
      end
      if(when_CoreDe10_l204) begin
        if(responseTimeout) begin
          responseStallCycles <= 21'h0;
        end else begin
          if(when_CoreDe10_l207) begin
            responseStallCycles <= (responseStallCycles + 21'h000001);
          end
        end
      end else begin
        responseStallCycles <= 21'h0;
      end
      if(requestTimeoutAccept) begin
        requestTimeoutSeen <= 1'b1;
      end
      if(responseTimeout) begin
        responseTimeoutSeen <= 1'b1;
      end
      if(captureNow) begin
        capturedValid <= 1'b1;
        capturedAddress <= cmdAddress;
        capturedData <= io_h2fLw_writedata;
        capturedMeta <= captureMetaNow;
      end
      if(wedgeNow) begin
        wedged <= 1'b1;
        wedgedWriteStallCycles <= 21'h100000;
      end
      if(localReadAccept) begin
        readData <= localReadData;
        readDataPending <= 1'b1;
      end
      if(when_CoreDe10_l263) begin
        if(when_CoreDe10_l264) begin
          droppedWrites <= (droppedWrites + 8'h01);
        end
      end
      if(when_CoreDe10_l269) begin
        cmdInFlight <= 1'b1;
        readRspPending <= selectedReadReq;
      end
      if(rspCompletesCurrent) begin
        cmdInFlight <= 1'b0;
        if(rspIsRead) begin
          readData <= io_cpuBus_rsp_payload_fragment_data;
          readDataPending <= 1'b1;
        end
        readRspPending <= 1'b0;
      end
      if(when_CoreDe10_l283) begin
        readData <= 32'h0;
        readDataPending <= 1'b1;
      end
      if(responseTimeout) begin
        cmdInFlight <= 1'b0;
        readRspPending <= 1'b0;
      end
      if(readDataPending) begin
        readDataPending <= 1'b0;
        readDataValid <= 1'b1;
      end
    end
  end


endmodule

