module SwapBuffer (
  input  wire          io_cmd_valid,
  output wire          io_cmd_ready,
  input  wire          io_vRetrace,
  input  wire          io_vsyncEnable,
  input  wire [7:0]    io_swapInterval,
  input  wire          io_swapCmdEnqueued,
  output wire          io_waiting,
  output wire [1:0]    io_swapCount,
  output wire [2:0]    io_swapsPending,
  input  wire          clk,
  input  wire          reset
);
  localparam State_Idle = 2'd0;
  localparam State_Sampling = 2'd1;
  localparam State_Waiting = 2'd2;

  reg        [1:0]    state_1;
  reg        [7:0]    retraceCounter;
  reg        [1:0]    swapCountReg;
  reg        [2:0]    swapsPendingReg;
  reg                 vRetracePrev;
  reg        [7:0]    capturedInterval;
  wire                vRetraceRising;
  reg                 swapCompleted;
  wire                when_SwapBuffer_l49;
  wire                when_SwapBuffer_l51;
  wire                io_cmd_fire;
  wire                when_SwapBuffer_l67;
  wire                when_SwapBuffer_l79;
  `ifndef SYNTHESIS
  reg [63:0] state_1_string;
  `endif


  `ifndef SYNTHESIS
  always @(*) begin
    case(state_1)
      State_Idle : state_1_string = "Idle    ";
      State_Sampling : state_1_string = "Sampling";
      State_Waiting : state_1_string = "Waiting ";
      default : state_1_string = "????????";
    endcase
  end
  `endif

  assign vRetraceRising = (io_vRetrace && (! vRetracePrev));
  always @(*) begin
    swapCompleted = 1'b0;
    case(state_1)
      State_Idle : begin
      end
      State_Sampling : begin
        if(when_SwapBuffer_l67) begin
          swapCompleted = 1'b1;
        end
      end
      default : begin
        if(vRetraceRising) begin
          if(when_SwapBuffer_l79) begin
            swapCompleted = 1'b1;
          end
        end
      end
    endcase
  end

  assign when_SwapBuffer_l49 = (io_swapCmdEnqueued && (! swapCompleted));
  assign when_SwapBuffer_l51 = ((! io_swapCmdEnqueued) && swapCompleted);
  assign io_waiting = (state_1 != State_Idle);
  assign io_swapCount = swapCountReg;
  assign io_swapsPending = swapsPendingReg;
  assign io_cmd_ready = (state_1 == State_Idle);
  assign io_cmd_fire = (io_cmd_valid && io_cmd_ready);
  assign when_SwapBuffer_l67 = (! io_vsyncEnable);
  assign when_SwapBuffer_l79 = (capturedInterval <= retraceCounter);
  always @(posedge clk or posedge reset) begin
    if(reset) begin
      state_1 <= State_Idle;
      retraceCounter <= 8'h0;
      swapCountReg <= 2'b00;
      swapsPendingReg <= 3'b000;
      vRetracePrev <= 1'b0;
      capturedInterval <= 8'h0;
    end else begin
      vRetracePrev <= io_vRetrace;
      if(when_SwapBuffer_l49) begin
        swapsPendingReg <= (swapsPendingReg + 3'b001);
      end else begin
        if(when_SwapBuffer_l51) begin
          swapsPendingReg <= (swapsPendingReg - 3'b001);
        end
      end
      case(state_1)
        State_Idle : begin
          if(io_cmd_fire) begin
            state_1 <= State_Sampling;
          end
        end
        State_Sampling : begin
          if(when_SwapBuffer_l67) begin
            swapCountReg <= (swapCountReg + 2'b01);
            state_1 <= State_Idle;
          end else begin
            state_1 <= State_Waiting;
            retraceCounter <= 8'h0;
            capturedInterval <= io_swapInterval;
          end
        end
        default : begin
          if(vRetraceRising) begin
            if(when_SwapBuffer_l79) begin
              swapCountReg <= (swapCountReg + 2'b01);
              state_1 <= State_Idle;
            end else begin
              retraceCounter <= (retraceCounter + 8'h01);
            end
          end
        end
      endcase
    end
  end


endmodule

